// generated by plugin/scripts/build.mjs from cli/src (piezas 0.7.4); do not edit by hand
// Part of the piezas CLI (see index.js).
//
// ===========================================================================
// The hook entries: what the plugin's hooks and a project's own hooks run
// ===========================================================================
//
// The Piezas checks reach an AI tool two ways, and both run this one file:
//   - the Claude Code / Codex plugin: plugin/hooks/hook.mjs and
//     pre-tool-use.mjs load it from the plugin's vendor/ copy;
//   - the project's own hooks, written by `piezas init` into
//     .claude/settings.json and .codex/hooks.json: they run the small file
//     .piezas/hooks/hook.mjs, which loads it from the project's installed
//     CLI (node_modules/piezas/src/hookentry.js) and calls runProjectHook.
//
// Two kinds of answer:
//   - 'context' (SessionStart, UserPromptSubmit, Stop): context for the AI, a
//     refused message, or a held turn. It never carries a permission decision,
//     so it can never approve a tool call, and a failure here never stops the
//     session (exit 0, a short note on stderr).
//   - 'pre-tool-use': never writes stdout, so it cannot approve. It ends with
//     exit 0 (the host's normal permission flow decides) or exit 2 with the
//     reason on stderr (refused). It fails closed.
//
// The plugin and the project hooks can both be installed; the host then runs
// both for every event.
//   - PreToolUse: both always check. Two refusals of one step is only a
//     repeated message; a check skipped is a real gap.
//   - Context events: the plugin always answers. The project's entry stays
//     quiet only when the plugin has marked this session for this project
//     (a small file in a private folder of the OS temp folder, written by the
//     plugin, fresh, a plain file owned by this user). A held turn or a refused
//     message is still given by the project's entry, marker or not: a marker
//     can at most make the owner see something twice, never let a check go.
import { createHash } from 'crypto';
import { existsSync, lstatSync, mkdirSync, readFileSync, readdirSync, realpathSync, unlinkSync, writeFileSync } from 'fs';
import { homedir, tmpdir } from 'os';
import { dirname, join, resolve } from 'path';
import { fileURLToPath } from 'url';
import { PROJECT_HOOK_MARKER } from './constants.js';
// A namespace import: the checks are looked up when called.
import * as checks from './hooks.js';

export const PRE_TOOL_FAILED = 'Piezas check could not run; refusing this step. (For the AI: run `npx piezas doctor` to see why.)';
export const PRE_TOOL_REFUSED = 'Piezas refused this step. (For the AI: run `npx piezas phase status` to see what comes next.)';

// How long the plugin's mark for a session counts: it is renewed on every
// event the plugin sees.
export const PLUGIN_MARKER_MAX_AGE_MS = 6 * 60 * 60 * 1000;
// State files older than this are cleaned up (at SessionStart and Stop).
const STATE_MAX_AGE_MS = 24 * 60 * 60 * 1000;
// At SessionStart both entries start together: the project's entry waits this
// long for the plugin's mark before it answers too.
const FIRST_EVENT_WAIT_MS = 400;

function currentUid() {
  return typeof process.getuid === 'function' ? process.getuid() : null;
}

// hookStateDir — where the plugin's "I am running" marks and the shim's
// once-per-session notices live: a private folder of this user in the OS
// temp folder (PIEZAS_HOOK_STATE_DIR replaces it). The project shim
// (.piezas/hooks/hook.mjs) computes the same folder.
export function hookStateDir(env = process.env) {
  if (typeof env.PIEZAS_HOOK_STATE_DIR === 'string' && env.PIEZAS_HOOK_STATE_DIR) return env.PIEZAS_HOOK_STATE_DIR;
  const uid = currentUid();
  return join(tmpdir(), `piezas-hooks-${uid === null ? 'user' : uid}`);
}

// safeStateDir — the folder, only when it is safe to use: a real folder (not a
// link), owned by this user, closed to everyone else. null otherwise (then
// both entries answer).
export function safeStateDir(env = process.env) {
  const dir = hookStateDir(env);
  try {
    mkdirSync(dir, { mode: 0o700 });
  } catch (error) {
    if (error?.code !== 'EEXIST') return null;
  }
  try {
    const st = lstatSync(dir);
    if (!st.isDirectory() || st.isSymbolicLink()) return null;
    const uid = currentUid();
    if (uid !== null && st.uid !== uid) return null;
    if (process.platform !== 'win32' && (st.mode & 0o077) !== 0) return null;
    return dir;
  } catch {
    return null;
  }
}

function sessionIdOf(payload) {
  return payload && typeof payload.session_id === 'string' && payload.session_id ? payload.session_id : null;
}

// hookProjectFor — the project folder (real path) whose own hooks this event
// may also reach: the nearest folder at or above cwd with both
// .piezas/hooks/hook.mjs and a package.json declaring piezas (the same
// test the hook launcher makes), never above the home folder.
export function hookProjectFor(cwd, env = process.env) {
  let d = resolve(cwd || process.cwd());
  const home = resolve(env.HOME || homedir());
  for (;;) {
    let pkg = '';
    try { pkg = readFileSync(join(d, 'package.json'), 'utf-8'); } catch { pkg = ''; }
    if (existsSync(join(d, PROJECT_HOOK_MARKER)) && /"piezas"\s*:/.test(pkg)) {
      try { return realpathSync(d); } catch { return d; }
    }
    const up = dirname(d);
    if (up === d || d === home) return null;
    d = up;
  }
}

// markerKey — one session in one project. The shim computes the same key.
export function markerKey(sessionId, projectDir) {
  return createHash('sha256').update(`${sessionId}\0${projectDir}`).digest('hex').slice(0, 32);
}

// eventKey — one event as both entries see it (the same payload): used to
// make the Stop hook's own records count it once.
export function eventKey(payload) {
  const pick = (k) => (payload[k] === undefined ? null : payload[k]);
  const parts = [
    pick('session_id'), pick('hook_event_name'), pick('tool_use_id'), pick('turn_id'), pick('prompt_id'), pick('source'),
    pick('prompt'), pick('tool_name'), pick('tool_input'), pick('stop_hook_active'), pick('last_assistant_message'),
  ];
  return createHash('sha256').update(JSON.stringify(parts)).digest('hex').slice(0, 40);
}

// markPluginActive — the plugin says, for this session in this project, that
// it is running. Written fresh (an old file, or a link put there, is removed
// first and never written through).
export function markPluginActive(payload, env = process.env) {
  const sid = sessionIdOf(payload);
  if (!sid) return;
  const project = hookProjectFor(payload.cwd);
  if (!project) return;
  const dir = safeStateDir(env);
  if (!dir) return;
  const file = join(dir, `plugin-${markerKey(sid, project)}`);
  try { unlinkSync(file); } catch { /* none yet */ }
  try { writeFileSync(file, new Date().toISOString(), { flag: 'wx', mode: 0o600 }); } catch { /* best effort */ }
}

// pluginActive — has the plugin marked this session in this project, recently,
// with a plain file of this user's?
export function pluginActive(payload, projectDir, { env = process.env, now = Date.now() } = {}) {
  const sid = sessionIdOf(payload);
  if (!sid || !projectDir) return false;
  const dir = safeStateDir(env);
  if (!dir) return false;
  let real;
  try { real = realpathSync(projectDir); } catch { real = resolve(projectDir); }
  try {
    const st = lstatSync(join(dir, `plugin-${markerKey(sid, real)}`));
    if (!st.isFile() || st.isSymbolicLink()) return false;
    const uid = currentUid();
    if (uid !== null && st.uid !== uid) return false;
    const age = now - st.mtimeMs;
    if (!(age > -60 * 1000 && age < PLUGIN_MARKER_MAX_AGE_MS)) return false;
    // A mark from before this session started is not this session's plugin.
    const started = sessionStartedAt(sid, real);
    return started === null || st.mtimeMs >= started - SESSION_START_SLACK_MS;
  } catch {
    return false;
  }
}

// When this session started in this project, as the project's own hooks saw
// it (in the project's guarded .piezas/quality-scan folder).
const SESSION_START_SLACK_MS = 10 * 1000;
function sessionsFile(projectDir) {
  return join(projectDir, '.piezas', 'quality-scan', 'sessions.json');
}
function sessionStartedAt(sid, projectDir) {
  try {
    const at = Date.parse(JSON.parse(readFileSync(sessionsFile(projectDir), 'utf-8'))?.[markerKey(sid, projectDir)]);
    return Number.isFinite(at) ? at : null;
  } catch {
    return null;
  }
}
export function recordSessionStart(payload, projectDir) {
  const sid = sessionIdOf(payload);
  if (!sid || !projectDir) return;
  let real;
  try { real = realpathSync(projectDir); } catch { real = resolve(projectDir); }
  try {
    let data = {};
    try { data = JSON.parse(readFileSync(sessionsFile(real), 'utf-8')) || {}; } catch { data = {}; }
    const entries = Object.entries(data).slice(-49);
    mkdirSync(dirname(sessionsFile(real)), { recursive: true });
    writeFileSync(sessionsFile(real), `${JSON.stringify({ ...Object.fromEntries(entries), [markerKey(sid, real)]: new Date().toISOString() }, null, 2)}\n`);
  } catch { /* best effort */ }
}

// sweepStateDir — remove our old files (marks, notices, and the claim files of
// an earlier build). Only plain files; a link is removed as a link.
export function sweepStateDir(env = process.env, now = Date.now()) {
  const dir = safeStateDir(env);
  if (!dir) return;
  try {
    for (const name of readdirSync(dir)) {
      if (!/^(?:claim|plugin|notice|stopnotice)-/.test(name)) continue;
      const path = join(dir, name);
      try {
        const st = lstatSync(path);
        if (st.isSymbolicLink() || now - st.mtimeMs > STATE_MAX_AGE_MS) unlinkSync(path);
      } catch { /* gone already */ }
    }
  } catch { /* best effort */ }
}

const silent = () => ({ code: 0, stdout: '', stderr: '' });

function sleep(ms) {
  return new Promise((done) => setTimeout(done, ms));
}

// runHookEntry — one event in, { code, stdout, stderr } out.
//   options: { entry: 'plugin' | 'project', kind: 'context' | 'pre-tool-use',
//              projectDir (project entry), rulesDir, cliPath, env }
export async function runHookEntry(payload, options = {}) {
  const env = options.env ?? process.env;
  const entry = options.entry === 'project' ? 'project' : 'plugin';
  const kind = options.kind === 'pre-tool-use' ? 'pre-tool-use' : 'context';
  if (kind === 'pre-tool-use') return preToolUseEntry(payload, { ...options, entry, env });

  if (!payload || typeof payload !== 'object') return silent();
  const event = payload.hook_event_name;
  if (entry === 'plugin') markPluginActive(payload, env);
  if (event === 'SessionStart' || event === 'Stop') sweepStateDir(env);

  // The project's entry, with the plugin running in this session: the plugin
  // gives the context. This entry still gives anything that holds or refuses.
  let deferring = false;
  if (entry === 'project') {
    const project = options.projectDir ?? hookProjectFor(payload.cwd);
    if (event === 'SessionStart') recordSessionStart(payload, project);
    deferring = pluginActive(payload, project, { env });
    if (!deferring && event === 'SessionStart' && sessionIdOf(payload)) {
      await sleep(FIRST_EVENT_WAIT_MS);
      deferring = pluginActive(payload, project, { env });
    }
  }
  if (deferring && event === 'SessionStart') return silent();
  // UserPromptSubmit and Stop run in full even behind the plugin's mark: the
  // owner's replies are always recorded (the second entry replays the first
  // one's notes), and a held turn or a refused message always goes out.
  // On a message, behind the mark, nothing else: the plugin's context is the
  // one the AI sees. On a Stop, the quality scan's lock decides: whichever
  // entry computes the stop shows the owner's line, the other only the hold.

  let out;
  try {
    // No session id: nothing to match the two entries' runs of one stop by.
    // Then only the plugin counts it (where the host sets CLAUDE_PLUGIN_ROOT,
    // the plugin is there); the project entry answers without counting.
    const noKey = !sessionIdOf(payload);
    out = await checks.phaseHook(payload, {
      rulesDir: options.rulesDir, cliPath: options.cliPath, confirm: true, env, eventId: noKey ? undefined : eventKey(payload),
      readOnly: noKey && entry === 'project' && event === 'Stop' && !!env.CLAUDE_PLUGIN_ROOT,
    });
  } catch (error) {
    return { code: 0, stdout: '', stderr: `piezas hook: ${error?.message || error}` };
  }
  let stdout = out?.stdout || '';
  if (stdout) {
    // Defense in depth: this kind only ever adds context or refuses a message.
    // Drop any permission decision so it can never approve a tool call.
    try {
      const answer = JSON.parse(stdout);
      if (answer?.hookSpecificOutput?.permissionDecision !== undefined) {
        delete answer.hookSpecificOutput.permissionDecision;
        delete answer.hookSpecificOutput.permissionDecisionReason;
        stdout = JSON.stringify(answer);
      }
      if (deferring && event === 'UserPromptSubmit' && answer?.decision !== 'block') stdout = '';
    } catch {
      stdout = '';
    }
  }
  return { code: out?.exitCode === 2 ? 2 : 0, stdout, stderr: out?.stderr || '' };
}

async function preToolUseEntry(payload, options) {
  const refuse = (reason) => ({ code: 2, stdout: '', stderr: reason });
  try {
    if (!payload || typeof payload !== 'object') return refuse(PRE_TOOL_FAILED);
    // Registered for PreToolUse only; anything else is not ours to refuse.
    if (payload.hook_event_name !== 'PreToolUse') return silent();
    if (options.entry === 'plugin') markPluginActive(payload, options.env);
    const out = await checks.phaseHook(payload, { rulesDir: options.rulesDir, cliPath: options.cliPath, env: options.env });
    if (out?.exitCode === 2) return refuse(String(out.stderr || '').trim() || PRE_TOOL_FAILED);
    if (out?.stdout) {
      const answer = JSON.parse(out.stdout)?.hookSpecificOutput;
      if (answer?.permissionDecision === 'deny') return refuse(String(answer.permissionDecisionReason || '').trim() || PRE_TOOL_REFUSED);
      return silent();
    }
    if (out && out.exitCode === 0) return silent(); // allowed: the host's normal permission flow decides
    return refuse(PRE_TOOL_FAILED);
  } catch {
    return refuse(PRE_TOOL_FAILED);
  }
}

// The rules the project's hooks read: the copy that ships with the installed CLI.
export function projectRulesDir() {
  // Always the installed CLI's own rules: the project's copy (.piezas/rules)
  // is for reading, and is not what the checks are told.
  return join(dirname(fileURLToPath(import.meta.url)), '..', 'rules');
}

// runProjectHook — what .piezas/hooks/hook.mjs calls with the host's event.
// One shim serves every event: PreToolUse is checked (fail closed), the
// others add context.
export async function runProjectHook(payload, options = {}) {
  const projectDir = options.projectDir;
  const kind = payload && typeof payload === 'object' && payload.hook_event_name === 'PreToolUse' ? 'pre-tool-use' : 'context';
  return runHookEntry(payload, {
    entry: 'project',
    kind,
    projectDir,
    rulesDir: projectDir ? projectRulesDir(projectDir) : undefined,
    env: options.env,
  });
}
